/bin/bash -lc "perl -E '
sub y{my("'$t)=@_; return sin($t*10.0)*exp(-$t)*2.0+1.0;}
for my $n (1..12){
  my @ys=map{y($_/($n*2.0))}(0..$n*2-1);
  my $min=$ys[0]; my $max=$ys[0];
  $min=$_ if $_<$min for @ys; $max=$_ if $_>$max for @ys;
  my $cross=0; for my $i (0..$#ys-1){$cross++ if ($ys[$i]==0)||($ys[$i]*$ys[$i+1]<0);} $cross++ if $ys[-1]*0<0; # last segment to base-right
  say "n=$n min=$min max=$max signs=", join(q{}, map{$_>0?qq{+}:$_<0?qq{-}:qq{0}} @ys), " crossings=$cross";
}
'"'"

