/bin/bash -lc "perl -E '
sub yy{my("'$t)=@_; return sin($t*10.0)*exp(-$t)*2.0+1.0;}
for my $n (1..12){
  my @idx = (0 .. ($n*2 - 1));
  my @ys = map { yy($_/($n*2.0)) } @idx;
  my $min=$ys[0]; my $max=$ys[0];
  for (@ys){ $min=$_ if $_<$min; $max=$_ if $_>$max; }
  my $cross=0;
  for my $i (0..$#ys-1){ $cross++ if ($ys[$i]==0) || ($ys[$i]*$ys[$i+1] < 0); }
  $cross++ if ($ys[-1] < 0);
  say "n=$n min=$min max=$max signs=", join(q{}, map { $_>0 ? q{+} : $_<0 ? q{-} : q{0} } @ys), " crossings=$cross";
}
'"'"

